309	/// Look up the description for a trigger from the card's TriggeredAbilityDef.
310	/// For transformed DFCs, also check the back face's triggered abilities.
311	fn trigger_description(registry: &CardRegistry, card_id: CardId, kind: &crate::cards::TriggerKind, is_transformed: bool) -> String {
312	    if let Some(behavior) = registry.get(card_id) {
313	        // Check front face triggers.
314	        if let Some(t) = behavior.card_data().triggered_abilities.iter().find(|t| &t.kind == kind) {
315	            return t.description.clone();
316	        }
317	        // For transformed DFCs, also check back face triggers.
318	        if is_transformed {
319	            if let Some(back) = behavior.back_face_data() {
320	                if let Some(t) = back.triggered_abilities.iter().find(|t| &t.kind == kind) {
321	                    return t.description.clone();
322	                }
323	            }
324	        }
325	    }
326	    String::new()
327	}
