1405	/// Generate legal discard actions for hand size.
1406	fn legal_discard_actions(state: &GameState, player: PlayerId, discard_count: usize) -> Vec<Action> {
1407	    let hand: Vec<ObjectId> = state.objects_in_zone(Zone::Hand, player)
1408	        .iter().map(|o| o.id).collect();
1409	
1410	    if hand.len() <= discard_count {
1411	        // Must discard all.
1412	        return vec![Action::DiscardCards { cards: hand }];
1413	    }
1414	
1415	    // Enumerate all combinations of `discard_count` cards from hand.
1416	    let combos = combinations(&hand, discard_count);
1417	    combos.into_iter()
1418	        .map(|cards| Action::DiscardCards { cards })
1419	        .collect()
1420	}
