1422	fn combinations(items: &[ObjectId], k: usize) -> Vec<Vec<ObjectId>> {
1423	    if k == 0 {
1424	        return vec![vec![]];
1425	    }
1426	    if items.len() < k {
1427	        return vec![];
1428	    }
1429	    let mut result = Vec::new();
1430	    for i in 0..=items.len() - k {
1431	        let rest = combinations(&items[i + 1..], k - 1);
1432	        for mut combo in rest {
1433	            combo.insert(0, items[i]);
1434	            result.push(combo);
1435	        }
1436	    }
1437	    result
1438	}
